export const dynamic = 'force-dynamic';
export const runtime = 'nodejs';
export const maxDuration = 300;

/**
 * Founder-local edition review.
 *
 * This route invokes the SAME deterministic member-book renderer used by the
 * owner-gated production route, but only for an ephemeral manuscript supplied
 * by the dedicated loopback review browser. It never authenticates a member,
 * reads a database/Source vault, records provenance, publishes, or retains an
 * artifact. Generated bytes are streamed once and the temp file is deleted.
 *
 * Production `exportsCertified` remains false. The process flag, loopback host
 * claims, and process-scoped capability token are all required on every request.
 */

import { NextRequest, NextResponse } from 'next/server';
import { promises as fs } from 'node:fs';
import { createHash } from 'node:crypto';
import {
  computeSourceHash,
  inspectBookProduction,
  renderMemberBook,
  type MemberBookSection,
} from '@/lib/manuscript/render/renderMemberBook';
import { verifyLocalReviewAuthority } from '@/lib/writersStudio/localReviewAuthority';

const MAX_SECTIONS = 500;
const MAX_TOTAL_CHARS = 2_000_000;
const MAX_SECTION_CHARS = 250_000;
const MAX_TITLE_CHARS = 200;
const MAX_AUTHOR_CHARS = 160;
const MAX_HEADING_CHARS = 500;

type ReviewFormat = 'pdf' | 'epub';
type ReviewInput = {
  action: 'inspect' | 'render';
  title: string;
  author: string | null;
  sections: MemberBookSection[];
  format?: ReviewFormat;
  expectedSourceHash?: string;
};

function json(body: unknown, status: number): NextResponse {
  return NextResponse.json(body, {
    status,
    headers: { 'Cache-Control': 'private, no-store' },
  });
}

function cleanFilename(title: string): string {
  const cleaned = title.replace(/[^\w.\- ]+/g, '').trim().slice(0, 110);
  return cleaned || 'manuscript';
}

function parseInput(value: unknown): { ok: true; value: ReviewInput } | { ok: false; error: string } {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return { ok: false, error: 'Invalid review request.' };
  }
  const body = value as Record<string, unknown>;
  if (body.action !== 'inspect' && body.action !== 'render') {
    return { ok: false, error: "action must be 'inspect' or 'render'" };
  }
  const title = typeof body.title === 'string' ? body.title.trim() : '';
  if (!title || title.length > MAX_TITLE_CHARS) {
    return { ok: false, error: 'A manuscript title is required (200 characters max).' };
  }
  const author = body.author === null || body.author === undefined
    ? null
    : typeof body.author === 'string' ? body.author.trim() : '__invalid__';
  if (author === '__invalid__' || (author?.length ?? 0) > MAX_AUTHOR_CHARS) {
    return { ok: false, error: 'Author must be text no longer than 160 characters.' };
  }
  if (!Array.isArray(body.sections) || body.sections.length === 0 || body.sections.length > MAX_SECTIONS) {
    return { ok: false, error: `Provide between 1 and ${MAX_SECTIONS} manuscript sections.` };
  }

  let total = 0;
  const sections: MemberBookSection[] = [];
  for (const candidate of body.sections) {
    if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
      return { ok: false, error: 'Each manuscript section must be an object.' };
    }
    const row = candidate as Record<string, unknown>;
    const heading = row.heading === null || row.heading === undefined
      ? null
      : typeof row.heading === 'string' ? row.heading : '__invalid__';
    if (heading === '__invalid__' || (heading?.length ?? 0) > MAX_HEADING_CHARS) {
      return { ok: false, error: 'A section heading is invalid or too long.' };
    }
    if (typeof row.body !== 'string' || row.body.length > MAX_SECTION_CHARS) {
      return { ok: false, error: 'A section body is invalid or too large.' };
    }
    const depth = row.headingDepth;
    if (depth !== undefined && depth !== null && depth !== 1 && depth !== 2 && depth !== 3) {
      return { ok: false, error: 'A section heading depth is invalid.' };
    }
    const signal = row.headingSignal;
    if (signal !== undefined && signal !== null && typeof signal !== 'string') {
      return { ok: false, error: 'A section heading signal is invalid.' };
    }
    total += row.body.length + (heading?.length ?? 0);
    if (total > MAX_TOTAL_CHARS) {
      return { ok: false, error: 'The local review manuscript is larger than 2 MB of text.' };
    }
    sections.push({
      heading,
      body: row.body,
      headingDepth: depth as 1 | 2 | 3 | null | undefined,
      headingSignal: signal as string | null | undefined,
    });
  }

  const format = body.format;
  if (body.action === 'render' && format !== 'pdf' && format !== 'epub') {
    return { ok: false, error: "format must be 'pdf' or 'epub'" };
  }
  const expectedSourceHash = body.expectedSourceHash;
  if (expectedSourceHash !== undefined
      && (typeof expectedSourceHash !== 'string' || !/^[a-f0-9]{64}$/i.test(expectedSourceHash))) {
    return { ok: false, error: 'The source witness is invalid.' };
  }
  return {
    ok: true,
    value: {
      action: body.action,
      title,
      author: author || null,
      sections,
      ...(format === 'pdf' || format === 'epub' ? { format } : {}),
      ...(typeof expectedSourceHash === 'string' ? { expectedSourceHash } : {}),
    },
  };
}

export async function POST(request: NextRequest) {
  const authority = verifyLocalReviewAuthority(request);
  if (!authority.ok) return json({ error: authority.error }, authority.status);

  let parsed: unknown;
  try {
    parsed = await request.json();
  } catch {
    return json({ error: 'Invalid JSON body' }, 400);
  }
  const admitted = parseInput(parsed);
  if (!admitted.ok) return json({ error: admitted.error }, 400);
  const input = admitted.value;
  const issues = inspectBookProduction(input.sections);
  const sourceHash = computeSourceHash(input.sections);

  if (input.action === 'inspect') {
    return json({
      ready: issues.length === 0,
      title: input.title,
      sectionCount: input.sections.length,
      sourceAuthority: 'local_review',
      sourceRevision: sourceHash,
      issues,
      publicationBoundary:
        'This local review creates one temporary file from the confirmed session manuscript. It does not publish, distribute, certify, or retain it.',
      localReview: true,
      persistent: false,
    }, 200);
  }

  if (issues.length > 0) {
    return json({ error: 'Resolve the production blockers before making a review artifact.', issues }, 409);
  }
  if (input.expectedSourceHash && input.expectedSourceHash !== sourceHash) {
    return json({ error: 'The local manuscript changed since the production check. Check again before making a file.' }, 409);
  }

  let filePath: string | null = null;
  try {
    const result = await renderMemberBook(input.sections, {
      title: input.title,
      author: input.author,
      format: input.format!,
    });
    filePath = result.filePath;
    const bytes = await fs.readFile(result.filePath);
    const artifactHash = createHash('sha256').update(bytes).digest('hex');
    console.log(
      `[writer/local-review] rendered { format: ${input.format}, sections: ${result.sectionCount}, `
        + `chars: ${input.sections.reduce((sum, section) => sum + section.body.length, 0)}, `
        + `source: ${result.sourceHash.slice(0, 12)}, artifact: ${artifactHash.slice(0, 12)}, `
        + `bytes: ${bytes.byteLength} }`,
    );
    const filename = `${cleanFilename(input.title)}-LOCAL-REVIEW.${input.format}`;
    return new NextResponse(new Uint8Array(bytes), {
      status: 200,
      headers: {
        'Content-Type': input.format === 'pdf' ? 'application/pdf' : 'application/epub+zip',
        'Content-Length': String(bytes.byteLength),
        'Content-Disposition': `attachment; filename="${filename}"; filename*=UTF-8''${encodeURIComponent(filename)}`,
        'Cache-Control': 'private, no-store',
        'X-Soullab-Local-Review': '1',
        'X-Soullab-Production-Profile': result.productionProfile,
        'X-Soullab-Source-Hash': result.sourceHash,
        'X-Soullab-Artifact-SHA256': artifactHash,
        'X-Soullab-Artifact-Bytes': String(bytes.byteLength),
        ...(Number.isInteger(result.pageCount) && (result.pageCount ?? 0) > 0
          ? { 'X-Soullab-Page-Count': String(result.pageCount) }
          : {}),
      },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`[writer/local-review] render failed { format: ${input.format}, reason: ${message.slice(0, 160)} }`);
    const toolingMissing = message.includes('ENOENT')
      || message.toLowerCase().includes('chromium')
      || message.includes('Browser was not found');
    return json({ error: 'The local review file could not be made just now.' }, toolingMissing ? 503 : 500);
  } finally {
    if (filePath) await fs.unlink(filePath).catch(() => undefined);
  }
}
